import{_ as a,o as i,c as e,a2 as t}from"./chunks/framework.DFwwXrrM.js";const u=JSON.parse('{"title":"桌面歌词","description":"","frontmatter":{},"headers":[],"relativePath":"guide/desktop-lyrics.md","filePath":"guide/desktop-lyrics.md","lastUpdated":null}'),r={name:"guide/desktop-lyrics.md"};function o(s,l,d,n,p,c){return i(),e("div",null,[...l[0]||(l[0]=[t('<h1 id="桌面歌词" tabindex="-1">桌面歌词 <a class="header-anchor" href="#桌面歌词" aria-label="Permalink to &quot;桌面歌词&quot;">​</a></h1><p>桌面歌词是 Still 的独立置顶窗口，适合在写作、浏览网页或处理其他任务时保留歌词视图。</p><h2 id="基础行为" tabindex="-1">基础行为 <a class="header-anchor" href="#基础行为" aria-label="Permalink to &quot;基础行为&quot;">​</a></h2><ul><li>可以从播放器打开或关闭桌面歌词</li><li>桌面歌词窗口会置顶显示</li><li>支持拖动位置</li><li>支持锁定，避免误拖动或遮挡操作</li><li>会记住窗口位置</li></ul><h2 id="显示模式" tabindex="-1">显示模式 <a class="header-anchor" href="#显示模式" aria-label="Permalink to &quot;显示模式&quot;">​</a></h2><p>桌面歌词支持：</p><ul><li>单行歌词</li><li>双行歌词</li><li>翻译显示</li><li>下一句显示</li><li>逐字高亮</li><li>歌词切换动画</li></ul><p>双行模式下，如果开启翻译并且当前歌曲有翻译歌词，第二行会显示译文；否则可以显示下一句原文。</p><h2 id="样式设置" tabindex="-1">样式设置 <a class="header-anchor" href="#样式设置" aria-label="Permalink to &quot;样式设置&quot;">​</a></h2><p>可以调整：</p><ul><li>主行字号</li><li>第二行字号</li><li>字重</li><li>已播放文字颜色</li><li>未播放文字颜色</li><li>描边色</li></ul><p>描边色支持 RGBA，用来在不同桌面背景上保持可读性。</p><h2 id="桌面歌词控制" tabindex="-1">桌面歌词控制 <a class="header-anchor" href="#桌面歌词控制" aria-label="Permalink to &quot;桌面歌词控制&quot;">​</a></h2><p>桌面歌词窗口中包含轻量控制能力，例如播放/暂停、锁定切换，以及跳转到桌面歌词设置。</p>',14)])])}const _=a(r,[["render",o]]);export{u as __pageData,_ as default};
